import React, { createContext, useContext, useState } from "react";
import { Player, FirestoreRiddle } from "../../validation/firestoreSchemas";

export type GameMode = "daily" | "classic" | "challenge";

interface AuthContextType {
  isAuthenticated: boolean;
  playerData: Player | null;
  isLoading: boolean;
  currentRiddle: FirestoreRiddle | null;
  isDailyChallengeAvailable: boolean | undefined;
  gameMode: GameMode;
  setGameMode: (mode: GameMode) => void;
  login: () => Promise<void>;
  logout: () => Promise<void>;
  updatePlayerClassicIndex: (newIndex: number) => Promise<void>;
  updatePlayerData: (updates: Partial<Player>) => Promise<void>;
  setCurrentRiddle: React.Dispatch<
    React.SetStateAction<FirestoreRiddle | null>
  >;
  fetchCurrentRiddle: (player: Player | null, mode: GameMode) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Create stable mock functions outside component
const mockLogin = jest.fn();
const mockLogout = jest.fn();
const mockUpdatePlayerClassicIndex = jest.fn();
const mockUpdatePlayerData = jest.fn();
const mockFetchCurrentRiddle = jest.fn();

// Mock implementation for testing
export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [playerData, setPlayerData] = useState<Player | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [currentRiddle, setCurrentRiddle] = useState<FirestoreRiddle | null>(
    null
  );
  const [isDailyChallengeAvailable, setIsDailyChallengeAvailable] = useState<
    boolean | undefined
  >(undefined);
  const [gameMode, setGameMode] = useState<GameMode>("daily");

  const login = mockLogin.mockImplementation(async () => {
    setIsAuthenticated(true);
  });

  const logout = mockLogout.mockImplementation(async () => {
    setIsAuthenticated(false);
    setPlayerData(null);
    setCurrentRiddle(null);
    setIsDailyChallengeAvailable(undefined);
  });

  const updatePlayerClassicIndex =
    mockUpdatePlayerClassicIndex.mockImplementation(
      async (newIndex: number) => {
        if (playerData) {
          setPlayerData({
            ...playerData,
            progress: { ...playerData.progress, classicIndex: newIndex },
          });
        }
      }
    );

  const updatePlayerData = mockUpdatePlayerData.mockImplementation(
    async (updates: Partial<Player>) => {
      if (playerData) {
        setPlayerData({ ...playerData, ...updates });
      }
    }
  );

  const fetchCurrentRiddle = mockFetchCurrentRiddle.mockImplementation(
    async (player: Player | null, mode: GameMode) => {
      // Mock implementation
    }
  );

  const value = {
    isAuthenticated,
    playerData,
    isLoading,
    currentRiddle,
    isDailyChallengeAvailable,
    gameMode,
    setGameMode,
    login,
    logout,
    updatePlayerClassicIndex,
    updatePlayerData,
    setCurrentRiddle,
    fetchCurrentRiddle,
  };

  // Expose methods for testing
  (value as any).__setAuthenticated = setIsAuthenticated;
  (value as any).__setPlayerData = setPlayerData;
  (value as any).__setIsLoading = setIsLoading;
  (value as any).__setIsDailyChallengeAvailable = setIsDailyChallengeAvailable;

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};
